INSERT INTO public.ingredients (product_id, name, name_kr, safety, description, sort_order) VALUES
  ('b4444444-4444-4444-4444-444444444444', 'Snail Secretion Filtrate', '달팽이 분비물 여과물', 'safe', '피부 재생과 보습에 효과적인 핵심 성분', 1),
  ('b4444444-4444-4444-4444-444444444444', 'Sodium Hyaluronate', '히알루론산나트륨', 'safe', '피부 깊숙이 수분을 공급하는 보습 성분', 2),
  ('b4444444-4444-4444-4444-444444444444', 'Niacinamide', '나이아신아마이드', 'safe', '피부 톤 개선과 모공 케어에 도움을 주는 성분', 3),
  ('b4444444-4444-4444-4444-444444444444', 'Allantoin', '알란토인', 'safe', '피부를 진정시키고 재생을 돕는 성분', 4),
  ('b4444444-4444-4444-4444-444444444444', 'Phenoxyethanol', '페녹시에탄올', 'caution', '방부제로 일부 민감한 피부에 刺激을 줄 수 있음', 5)
INSERT INTO public.ingredients (product_id, name, name_kr, safety, description, sort_order) VALUES
  ('b3333333-3333-3333-3333-333333333333', 'Betula Platyphylla Japonica Juice', '자작나무 수액', 'safe', '풍부한 미네랄로 피부에 수분을 공급하는 자작나무 수액', 1),
  ('b3333333-3333-3333-3333-333333333333', 'Glycerin', '글리세린', 'safe', '피부 수분을 붙잡아 주는 기초 보습 성분', 2),
  ('b3333333-3333-3333-3333-333333333333', 'Butylene Glycol', '부틸렌글라이콜', 'safe', '수분 보유력을 높이고 제형을 안정시키는 성분', 3),
  ('b3333333-3333-3333-3333-333333333333', 'Niacinamide', '나이아신아마이드', 'safe', '피부 톤 개선과 모공 케어에 도움을 주는 성분', 4),
  ('b3333333-3333-3333-3333-333333333333', 'Fragrance', '향료', 'caution', '제품에 향을 부여하나 민감성 피부에 자극이 될 수 있음', 5)
